fun Dutch_National_Flag(@init<table> array):
    n = length(array)

    // Three pointers: low, mid, high
    low = 0
    mid = 0
    high = n - 1

    // Process array until mid crosses high
    while (mid <= high):
        @mark<mid, outline, yellow> if (array[mid] == 0):
            // Found 0, swap with low pointer and move both pointers forward
            @mark<low, highlight, green> swap(array[low], array[mid])
            low += 1
            mid += 1
        else if (array[mid] == 1):
            // Found 1, leave in place and move mid pointer forward
            @mark<mid, text, fg> mid += 1
        else:
            // Found 2, swap with high pointer and move high pointer backward
            @mark<high, highlight, green> swap(array[mid], array[high])
            high -= 1
        end if
    end while

    return array
end fun

