fun Boyer_Moore_Voting(@init<table> nums, size):
    candidate = nums[0]
    count = 1

    // Phase 1: Find candidate
    for (i = 1; i < size; i += 1):
        @mark<i, outline, yellow> if (nums[i] == candidate):
            @mark<i, highlight, green> count += 1
        end if

        @mark<i, outline, yellow> if (nums[i] != candidate):
            @mark<i, highlight, green> count -= 1
        end if

        @mark<i, outline, yellow> if (count == 0):
            @mark<i, highlight, green> candidate = nums[i]
            @mark<i, highlight, green> count = 1
        end if
    end for

    return candidate
end fun

fun Verify_Candidate(@init<table> nums, candidate, size):
    count = 0

    // Count occurrences of candidate
    for (i = 0; i < size; i += 1):
        @mark<i, outline, yellow> if (nums[i] == candidate):
            @mark<i, highlight, green> count += 1
        end if
    end for

    // Check if it's majority
    @mark<count, highlight, green> if (count > floor(size / 2)):
        @log<info, "Majority found"> return candidate
    end if

    @log<warn, "No majority"> return -1
end fun

fun Majority_Element(@init<table> nums):
    size = length(nums)

    @mark<size, outline, yellow> if (size == 0):
        @log<error, "Empty array"> return -1
    end if

    @mark<size, outline, yellow> candidate = Boyer_Moore_Voting(nums, size)
    @mark<candidate, highlight, green> result = Verify_Candidate(nums, candidate, size)

    return result
end fun

