fun Remove_Duplicates(@init<table> array):
    n = length(array)

    // Handle edge case of empty array
    if (n == 0):
        return 0
    end if

    // Index for placing unique elements
    @mark<write_idx, outline, yellow> write_idx = 1

    // Iterate through array starting from second element
    for (i = 1; i < n; i += 1):
        // If current element is different from previous
        @mark<i, outline, yellow> if (array[i] != array[i - 1]):
            // Place it at write index
            @mark<write_idx, highlight, green> array[write_idx] = array[i]
            // Increment write index
            write_idx += 1
        end if
    end for

    // Return count of unique elements
    return write_idx
end fun

